Int SlowDeathBehavior::getProbabilityModifier(const DamageInfo *damageInfo) const
{
	Int overkill = (Int)(damageInfo->out.m_actualDamageDealt - damageInfo->out.m_actualDamageClipped);
	Real overkillFraction = (Real)overkill / getObject()->getBodyModule()->getMaxHealth();
	const SlowDeathBehaviorModuleData *data = static_cast<const SlowDeathBehaviorModuleData *>(getModuleData());
	Int atLeast = 1;
	Int modifier = (Int)(overkillFraction * data->m_modifierBonusPerOverkillPercent) + data->m_probabilityModifier;
	return largerOf(atLeast, modifier);
}

