void SlowDeathBehaviorModuleData::parseFX(INI *ini, void *instance, void *store, const void *userData)
{
	SlowDeathBehaviorModuleData *data = (SlowDeathBehaviorModuleData *)instance;
	Int phase = ini->scanIndexList(ini->getNextToken(), TheSlowDeathPhaseNames);
	const char *name = ini->getNextToken();
	if (name != NULL)
	{
		do
		{
			const FXList *fx = TheFXListStore->findFXList(name);
			data->m_fx[phase].push_back(fx);
			if (fx != NULL)
				data->m_hasLists |= 1;
			name = ini->getNextTokenOrNull();
		} while (name != NULL);
	}
}

